import sys
import os
import json
import csv
import datetime
from decimal import Decimal

# Mapping from rule_id and fact_name to the document, field, and value type.
# This encodes the decision rules provided.
RULE_MAP = {
    "lca.wage_105": {
        "offered wage": {"doc": "lca_disclosure", "field": "WAGE_RATE_OF_PAY_FROM", "type": "amount"},
        "prevailing wage": {"doc": "lca_disclosure", "field": "PREVAILING_WAGE", "type": "amount"},
    },
    "lca.three_years": {
        "begin date": {"doc": "lca_disclosure", "field": "BEGIN_DATE", "type": "date"},
        "end date": {"doc": "lca_disclosure", "field": "END_DATE", "type": "date"},
    }
}

def normalize_amount(s):
    """Parse a string into a Decimal, returning None if empty or invalid."""
    s = s.strip().replace(',', '').replace('$', '')
    if s == '':
        return None
    try:
        return Decimal(s)
    except Exception:
        return None

def normalize_date(s):
    """Parse a string into a date object. Handles Excel serial numbers and common date formats."""
    s = s.strip()
    if s == '':
        return None
    # Try Excel serial number
    try:
        serial = float(s)
        # Excel serial date: 1899-12-30 + serial days
        dt = datetime.datetime(1899, 12, 30) + datetime.timedelta(days=serial)
        return dt.date()
    except ValueError:
        pass
    # Try common date string formats
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d"):
        try:
            dt = datetime.datetime.strptime(s, fmt).date()
            return dt
        except ValueError:
            continue
    return None

def load_document_rows(packet_dir, doc_name):
    """Load a CSV file by its base name and return a dict mapping CASE_NUMBER to list of rows."""
    for filename in sorted(os.listdir(packet_dir)):
        base, ext = os.path.splitext(filename)
        if base == doc_name:
            filepath = os.path.join(packet_dir, filename)
            with open(filepath, newline='', encoding='utf-8-sig') as f:
                reader = csv.DictReader(f)
                index = {}
                for row in reader:
                    # Strip keys and values
                    clean_row = {}
                    for k, v in row.items():
                        if k is not None:
                            clean_row[k.strip()] = v.strip() if v is not None else ''
                    case_num = clean_row.get('CASE_NUMBER', '')
                    if case_num:
                        index.setdefault(case_num, []).append(clean_row)
                return index
    return {}

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest.get('pairs', [])
    facts = manifest.get('facts', {})

    # Determine which documents need to be loaded
    needed_docs = set()
    for rule_id, fact_list in facts.items():
        if rule_id in RULE_MAP:
            for fact_name in fact_list:
                if fact_name in RULE_MAP[rule_id]:
                    needed_docs.add(RULE_MAP[rule_id][fact_name]['doc'])

    # Load document indexes
    doc_indexes = {}
    for doc in needed_docs:
        doc_indexes[doc] = load_document_rows(packet_dir, doc)

    result = {}
    for pair in pairs:
        if '::' not in pair:
            continue
        rule_id, entity = pair.split('::', 1)
        fact_names = facts.get(rule_id, [])
        pair_result = {}
        for fact_name in fact_names:
            if rule_id not in RULE_MAP or fact_name not in RULE_MAP[rule_id]:
                pair_result[fact_name] = "ABSENT"
                continue
            rule_info = RULE_MAP[rule_id][fact_name]
            doc = rule_info['doc']
            field = rule_info['field']
            vtype = rule_info['type']
            index = doc_indexes.get(doc, {})
            rows = index.get(entity, [])
            values = []
            for row in rows:
                raw = row.get(field, '')
                if raw is None:
                    raw = ''
                raw = raw.strip()
                if raw == '':
                    continue
                if vtype == 'amount':
                    norm = normalize_amount(raw)
                elif vtype == 'date':
                    norm = normalize_date(raw)
                else:
                    norm = raw
                if norm is not None:
                    values.append(norm)
            if not values:
                pair_result[fact_name] = "ABSENT"
            else:
                # Check for conflicts
                unique = set()
                for v in values:
                    unique.add(v)
                if len(unique) == 1:
                    val = values[0]
                    if vtype == 'amount':
                        out_val = str(val)
                    elif vtype == 'date':
                        out_val = val.strftime("%Y-%m-%d")
                    else:
                        out_val = val
                    pair_result[fact_name] = [out_val, doc]
                else:
                    pair_result[fact_name] = "CONFLICT"
        result[pair] = pair_result

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()

