import os
import sys
import json
import csv
from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation

# Decision rules: for each rule and fact, the document, field, and value type.
RULES = {
    "lca.wage_105": {
        "offered wage": {"document": "lca_disclosure", "field": "WAGE_RATE_OF_PAY_FROM", "type": "wage"},
        "prevailing wage": {"document": "lca_disclosure", "field": "PREVAILING_WAGE", "type": "wage"},
    },
    "lca.three_years": {
        "begin date": {"document": "lca_disclosure", "field": "BEGIN_DATE", "type": "date"},
        "end date": {"document": "lca_disclosure", "field": "END_DATE", "type": "date"},
    },
}

def find_file(packet_dir, document_name):
    """Find a file in packet_dir whose name (without extension) matches document_name."""
    for filename in os.listdir(packet_dir):
        base, _ = os.path.splitext(filename)
        if base == document_name:
            return os.path.join(packet_dir, filename)
    return None

def read_csv(file_path):
    """Read a CSV file and return a list of dict rows."""
    with open(file_path, newline='', encoding='utf-8-sig') as f:
        reader = csv.DictReader(f)
        return list(reader)

def convert_date(value):
    """Convert a raw date string to YYYY-MM-DD.
    Handles Excel serial numbers and common date formats."""
    value = value.strip()
    if not value:
        return None
    # Try as Excel serial number
    try:
        serial = int(value)
        # Excel serial date conversion (valid for serials >= 61)
        base = datetime(1899, 12, 30)
        dt = base + timedelta(days=serial)
        return dt.strftime('%Y-%m-%d')
    except ValueError:
        pass
    # Try common date formats
    for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%d/%m/%Y'):
        try:
            dt = datetime.strptime(value, fmt)
            return dt.strftime('%Y-%m-%d')
        except ValueError:
            continue
    return value

def convert_wage(value):
    """Convert a raw wage string to a normalized decimal string."""
    value = value.strip()
    if not value:
        return None
    try:
        d = Decimal(value)
        s = str(d)
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        return s
    except InvalidOperation:
        return value

def normalize_value(value, type_):
    """Normalize a raw value based on its type."""
    if type_ == 'date':
        return convert_date(value)
    elif type_ == 'wage':
        return convert_wage(value)
    else:
        return value.strip() if value else None

def get_fact_result(packet_dir, rule_id, fact_name, entity):
    """Extract a single fact for an entity from the appropriate document."""
    if rule_id not in RULES or fact_name not in RULES[rule_id]:
        return "ABSENT"
    rule = RULES[rule_id][fact_name]
    document_name = rule['document']
    field_name = rule['field']
    type_ = rule['type']

    file_path = find_file(packet_dir, document_name)
    if not file_path:
        return "ABSENT"
    doc_name = os.path.splitext(os.path.basename(file_path))[0]

    rows = read_csv(file_path)
    values = []
    for row in rows:
        case_num = row.get('CASE_NUMBER', '').strip()
        if case_num == entity.strip():
            raw = row.get(field_name, '')
            norm = normalize_value(raw, type_)
            if norm is not None:
                values.append(norm)

    if not values:
        return "ABSENT"
    unique = set(values)
    if len(unique) == 1:
        return [values[0], doc_name]
    else:
        return "CONFLICT"

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest['pairs']
    facts_map = manifest['facts']
    output = {}

    for pair in pairs:
        rule_id, entity = pair.split('::', 1)
        fact_names = facts_map.get(rule_id, [])
        fact_results = {}
        for fact_name in fact_names:
            result = get_fact_result(packet_dir, rule_id, fact_name, entity)
            fact_results[fact_name] = result
        output[pair] = fact_results

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

