import sys
import os
import json
import csv
from datetime import date, timedelta
from decimal import Decimal

def excel_serial_to_date(serial):
    # Excel epoch 1899-12-30 correctly handles the 1900 leap-year bug for dates after 1900-02-28
    return date(1899, 12, 30) + timedelta(days=int(round(float(serial))))

# Map each fact name to its establishing field (per decision rules)
FACT_FIELDS = {
    "offered wage": "WAGE_RATE_OF_PAY_FROM",
    "prevailing wage": "PREVAILING_WAGE",
    "begin date": "BEGIN_DATE",
    "end date": "END_DATE",
}

DATE_FACTS = {"begin date", "end date"}
DOCUMENT = "lca_disclosure"

def parse_value(fact_name, raw):
    raw = raw.strip()
    if not raw:
        return None
    if fact_name in DATE_FACTS:
        return excel_serial_to_date(raw).strftime("%Y-%m-%d")
    else:
        # amount as decimal string, preserving digits, no scientific notation
        d = Decimal(raw)
        return format(d, "f")

def values_equal(fact_name, a, b):
    if fact_name in DATE_FACTS:
        return a == b
    try:
        return Decimal(a) == Decimal(b)
    except Exception:
        return a == b

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_map = manifest["facts"]

    csv_path = os.path.join(packet_dir, "lca_disclosure.csv")
    rows_by_case = {}
    with open(csv_path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            case = (row.get("CASE_NUMBER") or "").strip()
            if not case:
                continue
            rows_by_case.setdefault(case, []).append(row)

    result = {}
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts = facts_map.get(rule_id, [])
        rows = rows_by_case.get(entity, [])

        fact_result = {}
        for fact_name in facts:
            field = FACT_FIELDS.get(fact_name)
            parsed_values = []
            if field is not None:
                for row in rows:
                    raw = row.get(field, "") or ""
                    if not raw.strip():
                        continue
                    parsed_values.append(parse_value(fact_name, raw))

            if not parsed_values:
                fact_result[fact_name] = "ABSENT"
            else:
                first = parsed_values[0]
                if all(values_equal(fact_name, first, v) for v in parsed_values):
                    fact_result[fact_name] = [first, DOCUMENT]
                else:
                    fact_result[fact_name] = "CONFLICT"

        result[pair] = fact_result

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

